mapper.select:
SELECT 
FROM weekly_goal
WHERE user_id = #{userId}
  AND id = #{id}

mapper.update:
UPDATE weekly_goal
SET title = #{dto.title},
    type = #{dto.type},
    current_value = #{dto.currentValue},
    total_value = #{dto.totalValue},
    due_day = #{dto.dueDay}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE weekly_goal
SET achieved = #{achieved},
    current_value = #{currentValue},
    achieved_day = #{achievedDay,jdbcType=VARCHAR}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM weekly_goal
WHERE id = #{id}
  AND user_id = #{userId}
